const std = @import("std");

pub fn main() !void {
    const num: i32 = 28;

    std.debug.print("Factors of {}: ", .{num});

    for (1..num + 1) |i| {
        if (@mod(num, @as(i32, @intCast(i))) == 0) {
            std.debug.print("{} ", .{i});
        }
    }
    std.debug.print("\n", .{});
}
